    12	
    13	// Adapter is the only seam through which Fidelity's capture, declaration, and
    14	// observation stages may obtain external data.  The graph plugin can provide
    15	// snapshots and semantic diffs, while checkpoint transcript retrieval belongs
    16	// to the parent Entire/Brain layer; keeping both behind one interface prevents
    17	// that distinction leaking into reconciliation and rendering.
    18	type Adapter interface {
    19		CheckpointTranscript(context.Context, string) (string, error)
    20		CheckpointCommit(context.Context, string) (string, error)
    21		SymbolDictionary(context.Context) ([]Symbol, error)
    22		ChangedEntities(context.Context, string, string) ([]ChangedEntity, error)
    23	}
    24	
    25	type Symbol struct {
    26		ID            string
    27		QualifiedName string
    28		FilePath      string
    29		StartLine     int
    30	}
    31	
    32	type ChangedEntity struct {
    33		ID        string
    34		Name      string
    35		FilePath  string
    36		StartLine int
    37	}
    38	
    39	// NativeGraphAdapter is the implementation used by the Fidelity CLI. It uses
    40	// the in-process semantic provider for graph facts and Entire's documented
    41	// checkpoint command for stored transcript bytes.
    42	type NativeGraphAdapter struct {
    43		Repo            string
    44		ProviderVersion string
    45	}
    46	
    47	func (adapter NativeGraphAdapter) CheckpointTranscript(ctx context.Context, checkpointID string) (string, error) {
    48		if strings.TrimSpace(checkpointID) == "" {
    49			return "", fmt.Errorf("checkpoint transcript requires a checkpoint ID")
    50		}
    51		// Do not use a shell here. Checkpoint IDs are external input, and passing
    52		// them as a single argument keeps them data even if malformed. --transcript
    53		// is the purpose-built CLI export: unlike --full it emits stored JSONL only,
    54		// without a presentation layer that Fidelity would have to scrape.
    55		command := exec.CommandContext(ctx, "entire", "checkpoint", "explain", "--checkpoint", checkpointID, "--transcript", "--no-pager")
    56		command.Dir = adapter.Repo
    57		output, err := command.Output()
    58		if err != nil {
    59			return "", fmt.Errorf("read checkpoint transcript %q with Entire CLI: %w", checkpointID, err)
    60		}
    61		if len(output) == 0 {
    62			return "", fmt.Errorf("checkpoint transcript %q was empty", checkpointID)
    63		}
    64		return string(output), nil
    65	}
    66	
    67	// CheckpointCommit resolves the checkpoint trailer before Stage 3 passes a
    68	// concrete, local Git range to the semantic diff engine. The checkpoint ID is
    69	// intentionally never treated as a Git revision directly.
    70	func (adapter NativeGraphAdapter) CheckpointCommit(ctx context.Context, checkpointID string) (string, error) {
    71		if strings.TrimSpace(checkpointID) == "" {
    72			return "", fmt.Errorf("checkpoint commit requires a checkpoint ID")
    73		}
    74		commit, err := gitutil.FindCommitWithCheckpoint(ctx, adapter.Repo, checkpointID)
    75		if err != nil {
    76			return "", fmt.Errorf("resolve checkpoint %q to commit: %w", checkpointID, err)
    77		}
    78		return commit, nil
    79	}
    80	
    81	func (adapter NativeGraphAdapter) SymbolDictionary(ctx context.Context) ([]Symbol, error) {
    82		snapshot, err := sem.BuildProviderSnapshotWithOptions(ctx, adapter.Repo, adapter.ProviderVersion, sem.ProviderSnapshotOptions{
    83			NoNetwork: true,
    84			Profile:   sem.ProfileFull,
    85		})
    86		if err != nil {
    87			return nil, fmt.Errorf("build graph snapshot: %w", err)
    88		}
    89		symbols := make([]Symbol, 0, len(snapshot.Symbols))
    90		for _, symbol := range snapshot.Symbols {
    91			symbols = append(symbols, Symbol{
    92				ID: symbol.ID, QualifiedName: symbol.QualifiedName,
    93				FilePath: symbol.FilePath, StartLine: symbol.StartLine,
    94			})
    95		}
    96		return symbols, nil
    97	}
    98	
    99	func (adapter NativeGraphAdapter) ChangedEntities(ctx context.Context, base, head string) ([]ChangedEntity, error) {
   100		result, err := sem.AnalyzeGitRange(ctx, adapter.Repo, base, head, nil)
   101		if err != nil {
   102			return nil, fmt.Errorf("analyze graph diff: %w", err)
   103		}
   104		var entities []ChangedEntity
   105		for _, file := range result.Files {
   106			for _, change := range file.Changes {
   107				line := change.AfterStartLine
   108				if line == 0 {
   109					line = change.BeforeStartLine
   110				}
   111				entities = append(entities, ChangedEntity{
   112					ID:   fmt.Sprintf("%s:%s:%d", file.Path, change.Name, line),
   113					Name: change.Name, FilePath: file.Path, StartLine: line,
   114				})
   115			}
   116		}
   117		return entities, nil
   118	}
   119	
   120	// UnavailableAdapter is the safe default for the command skeleton.  It makes
   121	// the missing transcript capability explicit instead of pretending that a Git
   122	// trailer contains the agent's stated intent.
   123	type UnavailableAdapter struct{}
