   141	// Stage identifies a stable pipeline boundary.  It allows the CLI skeleton to
   142	// prove ordering today and lets later tickets replace one stage at a time.
   143	type Stage string
   144	
   145	const (
   146		StageCapture   Stage = "capture"
   147		StageDeclare   Stage = "declare"
   148		StageObserve   Stage = "observe"
   149		StageReconcile Stage = "reconcile"
   150		StageManifest  Stage = "manifest"
