     1	package fidelity
     2	
     3	import "strings"
     4	
     5	type EntityLocation struct {
     6		Entity string `json:"entity"`
     7		File   string `json:"file,omitempty"`
     8		Line   int    `json:"line,omitempty"`
     9	}
    10	
    11	type UnimplementedEntity struct {
    12		Entity string `json:"entity"`
    13		Reason string `json:"reason"`
    14	}
    15	
    16	type DirectReconciliation struct {
    17		Confirmed             []EntityLocation      `json:"confirmed"`
    18		DeclaredUnimplemented []UnimplementedEntity `json:"declared_unimplemented"`
    19	}
    20	
    21	// ReconcileDirectClaims performs the first two deterministic tiers. Matching
    22	// permits a graph diff's short entity name to satisfy a transcript's qualified
    23	// symbol name, but never performs fuzzy equivalence; that remains an explicit
    24	// later policy decision.
    25	func ReconcileDirectClaims(intent Intent, changes []ChangedEntity) DirectReconciliation {
    26		result := DirectReconciliation{
    27			Confirmed:             []EntityLocation{},
    28			DeclaredUnimplemented: []UnimplementedEntity{},
    29		}
    30		for _, claim := range intent.ExtractedEntities {
    31			matched := false
    32			for _, change := range changes {
    33				if !sameEntityName(claim.Name, change.Name) {
    34					continue
    35				}
    36				matched = true
    37				result.Confirmed = append(result.Confirmed, EntityLocation{
    38					Entity: claim.Name, File: change.FilePath, Line: change.StartLine,
    39				})
    40			}
    41			if !matched {
    42				result.DeclaredUnimplemented = append(result.DeclaredUnimplemented, UnimplementedEntity{
    43					Entity: claim.Name, Reason: "named in intent, no matching graph change detected",
    44				})
    45			}
    46		}
    47		return result
    48	}
    49	
    50	func sameEntityName(claim, changed string) bool {
    51		if claim == changed {
    52			return true
    53		}
    54		lastDot := strings.LastIndex(claim, ".")
    55		return lastDot >= 0 && claim[lastDot+1:] == changed
    56	}
