     8	// Verification is the structured result produced before renderer-specific
     9	// verdict.json fields are added. Its inputs all pass through Adapter, keeping
    10	// the CLI, parent Entire checkpoint store, and semantic provider separated.
    11	type Verification struct {
    12		CheckpointID     string               `json:"checkpoint_id"`
    13		BaseCheckpointID string               `json:"base_checkpoint_id,omitempty"`
    14		HeadCommit       string               `json:"head_commit"`
    15		BaseCommit       string               `json:"base_commit"`
    16		NoBaseline       bool                 `json:"no_baseline"`
    17		Intent           Intent               `json:"intent"`
    18		Changes          []ChangedEntity      `json:"changes"`
    19		Reconciliation   DirectReconciliation `json:"reconciliation"`
    20	}
    21	
    22	// Pipeline runs the five stable Fidelity stages against a real adapter. A
    23	// StageRunner remains optional instrumentation: it lets callers record or
    24	// render stage progress without allowing those concerns to read external data.
    25	type Pipeline struct {
    26		Adapter Adapter
    27		Runner  StageRunner
    28	}
    29	
    30	func (pipeline Pipeline) Run(ctx context.Context, request Request) (Verification, error) {
    31		if pipeline.Adapter == nil {
    32			return Verification{}, fmt.Errorf("Fidelity pipeline requires an adapter")
    33		}
    34		runStage := func(stage Stage) error {
    35			if pipeline.Runner == nil {
    36				return nil
    37			}
    38			if err := pipeline.Runner.RunStage(ctx, stage, request); err != nil {
    39				return fmt.Errorf("Fidelity %s stage: %w", stage, err)
    40			}
    41			return nil
    42		}
    43	
    44		if err := runStage(StageCapture); err != nil {
    45			return Verification{}, err
    46		}
    47		transcript, err := pipeline.Adapter.CheckpointTranscript(ctx, request.CheckpointID)
    48		if err != nil {
    49			return Verification{}, fmt.Errorf("Fidelity capture stage: %w", err)
    50		}
    51	
    52		if err := runStage(StageDeclare); err != nil {
    53			return Verification{}, err
    54		}
    55		symbols, err := pipeline.Adapter.SymbolDictionary(ctx)
    56		if err != nil {
    57			return Verification{}, fmt.Errorf("Fidelity declare stage: %w", err)
    58		}
    59		noBaseline := request.BaseCheckpointID == ""
    60		var baselineTranscript string
    61		if !noBaseline {
    62			baselineTranscript, err = pipeline.Adapter.CheckpointTranscript(ctx, request.BaseCheckpointID)
    63			if err != nil {
    64				return Verification{}, fmt.Errorf("Fidelity declare stage: %w", err)
    65			}
    66		}
    67		intent := DeclareIntent(transcript, baselineTranscript, symbols, noBaseline)
    68	
    69		if err := runStage(StageObserve); err != nil {
    70			return Verification{}, err
    71		}
    72		head, err := pipeline.Adapter.CheckpointCommit(ctx, request.CheckpointID)
    73		if err != nil {
    74			return Verification{}, fmt.Errorf("Fidelity observe stage: %w", err)
    75		}
    76		base := emptyTreeObjectID
    77		if !noBaseline {
    78			base, err = pipeline.Adapter.CheckpointCommit(ctx, request.BaseCheckpointID)
    79			if err != nil {
    80				return Verification{}, fmt.Errorf("Fidelity observe stage: %w", err)
    81			}
    82		}
    83		changes, err := pipeline.Adapter.ChangedEntities(ctx, base, head)
    84		if err != nil {
    85			return Verification{}, fmt.Errorf("Fidelity observe stage: %w", err)
    86		}
    87	
    88		if err := runStage(StageReconcile); err != nil {
    89			return Verification{}, err
    90		}
    91		reconciliation := ReconcileDirectClaims(intent, changes)
    92	
    93		if err := runStage(StageManifest); err != nil {
    94			return Verification{}, err
    95		}
    96		return Verification{
    97			CheckpointID: request.CheckpointID, BaseCheckpointID: request.BaseCheckpointID,
    98			HeadCommit: head, BaseCommit: base, NoBaseline: noBaseline,
    99			Intent: intent, Changes: changes, Reconciliation: reconciliation,
   100		}, nil
   101	}
