   123			Verification: verification,
   124			Message:      "transcript capture, graph-grounded declaration, and direct reconciliation are complete; reachability tiers and verdict file rendering are not yet implemented",
   125		}
   126		encoder := json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout))
   127		encoder.SetEscapeHTML(false)
   128		return encoder.Encode(response)
