217		}
218	}
219	
220	func scopeLanguageLabel(scope completenessScope) string {
221		if scope.Language == "" {
222			return "this query"
223		}
224		return scope.Language
225	}
226	
227	func scopeLanguageFileCount(scope completenessScope) string {
228		if scope.LanguageFiles == 0 {
229			return "the query's language"
230		}
231		return fmt.Sprintf("%d file%s parsed", scope.LanguageFiles, pluralSuffix(scope.LanguageFiles))
232	}
233	
234	// compactCompletenessLine is the byte-capped form used by `--format agent`. It
235	// carries the same scoped verdict as the text banner in a fraction of the bytes:
236	// `<failed>/<files>` for the query's own scope, and one count for everything
237	// that cannot affect it.
238	func compactCompletenessLine(scope completenessScope, stats sem.ProviderStats) string {
239		label := ""
240		if scope.Language != "" {
241			label = scope.Language + " "
242		}
243		if scope.LanguageFailed == 0 && len(scope.InScopeWarnings) == 0 {
244			if scope.OtherFailures == 0 {
245				return ""
246			}
247			return fmt.Sprintf("C:%sclean F%d-other\n", label, scope.OtherFailures)
248		}
249		level := stats.CompletenessLevel
250		if level == "" {
251			level = "degraded"
252		}
253		return fmt.Sprintf("C:%s %s%d/%d W%d F%d-other\n",
254			level, label, scope.LanguageFailed, scope.LanguageFiles,
255			len(scope.InScopeWarnings), scope.OtherFailures)
256	}
257	
258	// writeIndexCostNotice states, on a cold run with nowhere to cache, that the
259	// cost just paid will be paid again.
260	//
261	// The relation verbs index the whole repository; `search` parses only its
262	// candidate files. That asymmetry is invisible from the CLI surface, so a reader
263	// cannot budget for it — and the natural reaction to an unexplained 26-second
264	// call is to batch queries into one command, which costs more, not less. One
265	// line, only when it is actionable.
266	func writeIndexCostNotice(out io.Writer, cacheHit, cacheDisabled bool) {
267		if cacheHit || !cacheDisabled {
268			return
269		}
270		fmt.Fprintln(out, "Index not cached (no --cache-dir, ENTIRE_PLUGIN_DATA_DIR unset): relation queries index the whole repository, and the next one will pay this cost again. Pass --cache-dir to reuse it.")
271	}
272	
273	// completenessScopeOrAll returns a usable scope for a response that carries
274	// diagnostics but no scope of its own. Scoping decides what is PRESENTED; it
275	// must never be able to drop coverage reporting because a field was left unset,
276	// so the fallback treats every diagnostic as in scope — the safe direction.
277	func completenessScopeOrAll(
278		scope completenessScope,
279		warnings []sem.ProviderWarning,
280		partialFailures []sem.PartialFailure,
281		stats sem.ProviderStats,
282	) completenessScope {
283		if scope.Language != "" || scope.LanguageFailed > 0 || scope.OtherFailures > 0 ||
284			len(scope.InScopeWarnings) > 0 || len(scope.InScopeFailures) > 0 {
285			return scope
286		}
287		if len(warnings) == 0 && len(partialFailures) == 0 {
288			return scope
289		}
290		rebuilt := completenessScope{LanguageFiles: stats.Files, Level: stats.CompletenessLevel}
291		for _, warning := range warnings {
292			if warning.Code == worktreeProvenanceWarning {
293				rebuilt.Worktree = true
294				continue
295			}
296			if len(rebuilt.InScopeWarnings) < maxScopedDiagnostics {
297				rebuilt.InScopeWarnings = append(rebuilt.InScopeWarnings, warning)
298			}
299		}
300		rebuilt.LanguageFailed = len(partialFailures)
301		for _, failure := range partialFailures {
302			if len(rebuilt.InScopeFailures) < maxScopedDiagnostics {
303				rebuilt.InScopeFailures = append(rebuilt.InScopeFailures, failure)
304			}
305		}
306		return rebuilt
307	}

