package fidelity

// reachability.go implements Build Map #21: N-hop reachability over the
// relation graph, computed twice — once restricted to deterministic edges
// (for expected_blast_radius, #23), once over every edge (to detect the
// advisory-only case, #25). The two are kept as separate BFS passes rather
// than one pass with a "best edge class seen" merge, because #23 requires
// deterministic-edge-only reasoning never to rest on an inferred/ambiguous
// hop — mixing them in one traversal risks a deterministic-looking path that
// silently used an advisory edge partway through.

// reachabilityHit is one entity's shortest path back to a confirmed entity.
type reachabilityHit struct {
	Hops               int
	Path               []string // symbol IDs, confirmed entity first
	EdgeTypesTraversed []string
	MinEdgeClass       string // "deterministic" or "advisory"
}

// symbolIndex resolves a ChangedEntity to the graph symbol ID reachability
// walks over. Matching permits a diff's short entity name to satisfy a
// snapshot's qualified name (sameEntityName, reused from reconcile.go) plus a
// same-file check, since two files can each define a same-named symbol.
func symbolIDForEntity(entity ChangedEntity, symbols []Symbol) (string, bool) {
	for _, symbol := range symbols {
		if symbol.FilePath == entity.FilePath && sameEntityName(symbol.QualifiedName, entity.Name) {
			return symbol.ID, true
		}
	}
	return "", false
}

// reachable runs bounded BFS from every ID in from, over relations restricted
// to edgeClass (or every relation when edgeClass is empty), up to hops. The
// graph is walked as undirected: a change to either a caller or a callee of a
// confirmed entity is a real blast-radius candidate, matching the CLI
// `impact` command's own both-directions framing.
func reachable(from []string, relations []GraphRelation, config Config, edgeClass EdgeClass, hops int) map[string]reachabilityHit {
	type step struct {
		id, edgeType string
	}
	adjacency := map[string][]step{}
	for _, relation := range relations {
		if edgeClass != "" && ClassifyRelation(GraphRelation{Confidence: relation.Confidence, Resolution: relation.Resolution}, config) != edgeClass {
			continue
		}
		adjacency[relation.FromID] = append(adjacency[relation.FromID], step{relation.ToID, relation.Type})
		adjacency[relation.ToID] = append(adjacency[relation.ToID], step{relation.FromID, relation.Type})
	}
	result := map[string]reachabilityHit{}
	visited := map[string]bool{}
	type queued struct {
		id                 string
		depth              int
		path               []string
		edgeTypesTraversed []string
	}
	var queue []queued
	for _, id := range from {
		visited[id] = true
		queue = append(queue, queued{id: id, depth: 0, path: []string{id}})
	}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		if current.depth >= hops {
			continue
		}
		for _, next := range adjacency[current.id] {
			if visited[next.id] {
				continue
			}
			visited[next.id] = true
			path := append(append([]string{}, current.path...), next.id)
			edgeTypes := append(append([]string{}, current.edgeTypesTraversed...), next.edgeType)
			minClass := "deterministic"
			if edgeClass == "" {
				// Whole-graph pass: report the weakest class actually crossed,
				// since a caller of the whole-graph result cares whether ANY
				// hop was advisory.
				minClass = string(EdgeAdvisory)
				for _, relation := range relations {
					if (relation.FromID == current.id && relation.ToID == next.id) || (relation.ToID == current.id && relation.FromID == next.id) {
						if ClassifyRelation(GraphRelation{Confidence: relation.Confidence, Resolution: relation.Resolution}, config) == EdgeDeterministic {
							minClass = string(EdgeDeterministic)
						}
					}
				}
			}
			result[next.id] = reachabilityHit{
				Hops: current.depth + 1, Path: path,
				EdgeTypesTraversed: edgeTypes, MinEdgeClass: minClass,
			}
			queue = append(queue, queued{id: next.id, depth: current.depth + 1, path: path, edgeTypesTraversed: edgeTypes})
		}
	}
	return result
}

package fidelity

// coverage.go implements Build Map #33: the coverage-confidence signal, the
// mandatory Curveball (Track 2, "Graph Is Evidence, Not an Oracle") response.
//
// This is orthogonal to EdgeClass (classify.go): EdgeClass classifies
// confidence in a relation the graph DID record. CoverageConfidence
// classifies whether the graph's SILENCE about an entity means anything at
// all — the gap the Curveball names: a changed entity with zero relations was
// being filed as confident undeclared_scope_creep regardless of WHY the graph
// was silent (genuinely disconnected code, vs. dynamic dispatch / generated
// code / reflection that static analysis cannot follow).
type CoverageConfidence string

const (
	// CoverageFull: the entity's relationships are backed by normal static
	// extraction; a zero-hop result from here is a real "not connected."
	CoverageFull CoverageConfidence = "full"
	// CoveragePartial: the entity sits in a region static analysis is known
	// to degrade in, or has zero extracted-class edges despite real code
	// presence with no stronger signal ruling that out.
	CoveragePartial CoverageConfidence = "partial"
	// CoverageUnknown: coverage itself could not be determined this run — the
	// snapshot returned no data at all for this entity's file.
	CoverageUnknown CoverageConfidence = "unknown"
)

// ComputeCoverage implements both detection mechanisms named in config
// coverage.detect_via. "capabilities_api" reads the provider's own
// completeness signals (file presence, language tier, partial failures)
// before falling back to edge counting; "heuristic_zero_edge" is the edge
// count alone, exactly as named, with no unknown case — #7/#37 confirmed
// capabilities_api is real for this provider, so it is the config default.
func ComputeCoverage(entity ChangedEntity, symbolID string, symbolFound bool, graph GraphSnapshot, config Config) (CoverageConfidence, string) {
	deterministicEdges := countDeterministicEdges(symbolID, symbolFound, graph.Relations, config)

	if config.Coverage.DetectVia == "heuristic_zero_edge" {
		if deterministicEdges > 0 {
			return CoverageFull, ""
		}
		return zeroEdgeCoverage(config), "zero extracted-class edges detected for this symbol (heuristic_zero_edge: code presence not otherwise checked)"
	}

	// capabilities_api: consult the provider's own signals first.
	language, fileKnown := graph.FileLanguages[entity.FilePath]
	if !fileKnown {
		return CoverageUnknown, "file absent from the graph snapshot; the snapshot returned no data for this region, so coverage could not be determined"
	}
	if graph.PartialFailureFiles[entity.FilePath] {
		return CoverageUnknown, "the graph snapshot reported a partial failure for this file, so its relations may be incomplete"
	}
	if tier := graph.LanguageTiers[language]; tier == "inventory-only" {
		return CoveragePartial, "this file's language (" + language + ") is inventory-only: the graph records file/symbol structure but does not attempt relationship extraction for it"
	}
	if !symbolFound {
		return CoveragePartial, "entity could not be grounded to a symbol in the graph snapshot; it may be dynamically dispatched, generated, or otherwise unresolvable to static analysis"
	}
	if deterministicEdges > 0 {
		return CoverageFull, ""
	}
	return zeroEdgeCoverage(config), "zero extracted-class edges detected for this symbol despite real code presence; static analysis may not have resolved dynamic dispatch, generated code, or reflection here"
}

func zeroEdgeCoverage(config Config) CoverageConfidence {
	if config.Coverage.TreatZeroEdgeAs == "full" {
		return CoverageFull
	}
	return CoveragePartial
}

func countDeterministicEdges(symbolID string, symbolFound bool, relations []GraphRelation, config Config) int {
	if !symbolFound {
		return 0
	}
	count := 0
	for _, relation := range relations {
		if relation.FromID != symbolID && relation.ToID != symbolID {
			continue
		}
		if ClassifyRelation(relation, config) == EdgeDeterministic {
			count++
		}
	}
	return count
}

package fidelity

import "strings"

type EntityLocation struct {
	Entity string `json:"entity"`
	File   string `json:"file,omitempty"`
	Line   int    `json:"line,omitempty"`
	// CoverageConfidence is stamped even on success: a confirmed match still
	// tells a reviewer how much of the surrounding graph it rests on (#33).
	CoverageConfidence CoverageConfidence `json:"coverage_confidence"`
}

type UnimplementedEntity struct {
	Entity string `json:"entity"`
	Reason string `json:"reason"`
}

// BlastRadiusEntity is one expected_blast_radius entry (#23): a changed
// entity reachable from a confirmed one within blast_radius_hops via
// deterministic edges only. Never rests on an inferred/ambiguous hop.
type BlastRadiusEntity struct {
	Entity              string             `json:"entity"`
	File                string             `json:"file,omitempty"`
	Line                int                `json:"line,omitempty"`
	PathFromConfirmed   []string           `json:"path_from_confirmed"`
	Hops                int                `json:"hops"`
	EdgeTypesTraversed  []string           `json:"edge_types_traversed"`
	MinEdgeClass        string             `json:"min_edge_class"`
	CoverageConfidence  CoverageConfidence `json:"coverage_confidence"`
}

// ScopeCreepEntity is one undeclared_scope_creep entry (#24): unreachable
// from any confirmed entity within the hop limit, AND its coverage is full —
// #34's never-silently-upgrade rule means this tier is reachable only when
// the absence of a path is itself trustworthy evidence.
type ScopeCreepEntity struct {
	Entity             string             `json:"entity"`
	File               string             `json:"file,omitempty"`
	Line               int                `json:"line,omitempty"`
	Reason             string             `json:"reason"`
	CoverageConfidence CoverageConfidence `json:"coverage_confidence"`
}

// AdvisoryEntity is one advisory_low_confidence entry (#25): reachable from a
// confirmed entity only via an inferred/ambiguous-equivalent (advisory) edge.
// The Databricks-reserved fields stay nil/zero-value until the calibration
// module (§12) populates them; never silently promoted to expected_blast_radius.
type AdvisoryEntity struct {
	Entity              string             `json:"entity"`
	File                string             `json:"file,omitempty"`
	Line                int                `json:"line,omitempty"`
	EdgeClass           string             `json:"edge_class"`
	Reason              string             `json:"reason"`
	CoverageConfidence  CoverageConfidence `json:"coverage_confidence"`
	VerbalConfidence     *float64           `json:"verbal_confidence"`
	ConformalGatePassed  *bool              `json:"conformal_gate_passed"`
	CalibratedConfidence *float64           `json:"calibrated_confidence,omitempty"`
	Corroboration        Corroboration      `json:"corroboration"`
}

// UnverifiableCoverageEntity is the new sixth tier (#34, #36): an entity that
// would otherwise have landed in undeclared_scope_creep on the strength of an
// absent path alone, but whose coverage is partial or unknown. Never
// conflated with AdvisoryEntity: that tier means "the graph has an edge but
// isn't sure about it"; this one means "the graph may not have tried to
// record an edge here at all."
type UnverifiableCoverageEntity struct {
	Entity             string             `json:"entity"`
	File               string             `json:"file,omitempty"`
	Line               int                `json:"line,omitempty"`
	CoverageConfidence CoverageConfidence `json:"coverage_confidence"`
	CoverageReason     string             `json:"coverage_reason"`
	// VerificationPath is the baseline safety guarantee (#35): populated with
	// or without Databricks. "manual_review_recommended" is the fallback.
	VerificationPath string        `json:"verification_path"`
	Corroboration    Corroboration `json:"corroboration"`
}

// Corroboration is the Databricks AI Search corroboration result (§12.4,
// §12.15), shared by advisory edges and unverifiable_coverage entries.
// Attempted is false and Verified/EvidenceSnippet are nil until the
// Databricks module runs; the schema shape does not change either way.
type Corroboration struct {
	Attempted       bool    `json:"attempted"`
	Verified        *bool   `json:"verified"`
	EvidenceSnippet *string `json:"evidence_snippet"`
}

// Reconciliation is Stage 4's full six-tier output (#22-#25, #33-#34).
type Reconciliation struct {
	Confirmed             []EntityLocation             `json:"confirmed"`
	DeclaredUnimplemented []UnimplementedEntity         `json:"declared_unimplemented"`
	ExpectedBlastRadius   []BlastRadiusEntity            `json:"expected_blast_radius"`
	UndeclaredScopeCreep  []ScopeCreepEntity             `json:"undeclared_scope_creep"`
	AdvisoryLowConfidence []AdvisoryEntity               `json:"advisory_low_confidence"`
	UnverifiableCoverage  []UnverifiableCoverageEntity   `json:"unverifiable_coverage"`
}

// DirectReconciliation is the original two-tier result (confirmed,
// declared_unimplemented) kept for its own tests and as the input to the
// fuller Reconcile below; it performs no graph reachability itself.
type DirectReconciliation struct {
	Confirmed             []EntityLocation      `json:"confirmed"`
	DeclaredUnimplemented []UnimplementedEntity `json:"declared_unimplemented"`
}

// ReconcileDirectClaims performs the first two deterministic tiers. Matching
// permits a graph diff's short entity name to satisfy a transcript's qualified
// symbol name, but never performs fuzzy equivalence; that remains an explicit
// later policy decision.
func ReconcileDirectClaims(intent Intent, changes []ChangedEntity) DirectReconciliation {
	result := DirectReconciliation{
		Confirmed:             []EntityLocation{},
		DeclaredUnimplemented: []UnimplementedEntity{},
	}
	for _, claim := range intent.ExtractedEntities {
		matched := false
		for _, change := range changes {
			if !sameEntityName(claim.Name, change.Name) {
				continue
			}
			matched = true
			result.Confirmed = append(result.Confirmed, EntityLocation{
				Entity: claim.Name, File: change.FilePath, Line: change.StartLine,
			})
		}
		if !matched {
			result.DeclaredUnimplemented = append(result.DeclaredUnimplemented, UnimplementedEntity{
				Entity: claim.Name, Reason: "named in intent, no matching graph change detected",
			})
		}
	}
	return result
}

// Reconcile is the full Stage 4: direct claims, then N-hop reachability
// (#21) tiering every remaining changed entity, with coverage-confidence
// (#33) checked BEFORE any entity can be filed as undeclared_scope_creep
// (#34) — the never-silently-upgrade rule the Curveball requires.
func Reconcile(intent Intent, changes []ChangedEntity, graph GraphSnapshot, config Config) Reconciliation {
	direct := ReconcileDirectClaims(intent, changes)

	confirmedIDs := map[string]bool{}
	confirmedNames := map[string]bool{}
	for _, confirmed := range direct.Confirmed {
		confirmedNames[confirmed.Entity+"|"+confirmed.File] = true
	}
	for _, change := range changes {
		if !isConfirmedChange(change, direct.Confirmed) {
			continue
		}
		if id, ok := symbolIDForEntity(change, graph.Symbols); ok {
			confirmedIDs[id] = true
		}
	}
	var confirmedIDList []string
	for id := range confirmedIDs {
		confirmedIDList = append(confirmedIDList, id)
	}

	deterministicHits := reachable(confirmedIDList, graph.Relations, config, EdgeDeterministic, config.BlastRadiusHops)
	anyEdgeHits := reachable(confirmedIDList, graph.Relations, config, "", config.BlastRadiusHops)

	result := Reconciliation{
		Confirmed:             stampConfirmedCoverage(direct.Confirmed, changes, graph, config),
		DeclaredUnimplemented: direct.DeclaredUnimplemented,
		ExpectedBlastRadius:   []BlastRadiusEntity{},
		UndeclaredScopeCreep:  []ScopeCreepEntity{},
		AdvisoryLowConfidence: []AdvisoryEntity{},
		UnverifiableCoverage:  []UnverifiableCoverageEntity{},
	}

	for _, change := range changes {
		if isConfirmedChange(change, direct.Confirmed) {
			continue
		}
		symbolID, symbolFound := symbolIDForEntity(change, graph.Symbols)
		coverage, coverageReason := ComputeCoverage(change, symbolID, symbolFound, graph, config)

		if symbolFound {
			if hit, ok := deterministicHits[symbolID]; ok {
				result.ExpectedBlastRadius = append(result.ExpectedBlastRadius, BlastRadiusEntity{
					Entity: change.Name, File: change.FilePath, Line: change.StartLine,
					PathFromConfirmed: hit.Path, Hops: hit.Hops,
					EdgeTypesTraversed: hit.EdgeTypesTraversed, MinEdgeClass: "deterministic",
					CoverageConfidence: coverage,
				})
				continue
			}
		}

		// #34: coverage is checked BEFORE undeclared_scope_creep can be
		// assigned on the strength of an absent path alone.
		if coverage != CoverageFull {
			result.UnverifiableCoverage = append(result.UnverifiableCoverage, UnverifiableCoverageEntity{
				Entity: change.Name, File: change.FilePath, Line: change.StartLine,
				CoverageConfidence: coverage, CoverageReason: coverageReason,
				VerificationPath: config.Coverage.FallbackVerificationPath,
				Corroboration:    Corroboration{Attempted: false},
			})
			continue
		}

		if symbolFound {
			if hit, ok := anyEdgeHits[symbolID]; ok {
				result.AdvisoryLowConfidence = append(result.AdvisoryLowConfidence, AdvisoryEntity{
					Entity: change.Name, File: change.FilePath, Line: change.StartLine,
					EdgeClass: "advisory",
					Reason:    "reachable from a confirmed entity within " + hopsWord(hit.Hops) + " only via an inferred/ambiguous edge",
					CoverageConfidence: coverage,
					Corroboration:      Corroboration{Attempted: false},
				})
				continue
			}
		}

		result.UndeclaredScopeCreep = append(result.UndeclaredScopeCreep, ScopeCreepEntity{
			Entity: change.Name, File: change.FilePath, Line: change.StartLine,
			Reason:             "changed, not reachable from any confirmed entity within " + hopsWord(config.BlastRadiusHops),
			CoverageConfidence: coverage,
		})
	}
	return result
}

func stampConfirmedCoverage(confirmed []EntityLocation, changes []ChangedEntity, graph GraphSnapshot, config Config) []EntityLocation {
	stamped := make([]EntityLocation, len(confirmed))
	for i, entry := range confirmed {
		stamped[i] = entry
		for _, change := range changes {
			if change.FilePath != entry.File || change.StartLine != entry.Line {
				continue
			}
			symbolID, symbolFound := symbolIDForEntity(change, graph.Symbols)
			coverage, _ := ComputeCoverage(change, symbolID, symbolFound, graph, config)
			stamped[i].CoverageConfidence = coverage
			break
		}
	}
	return stamped
}

func isConfirmedChange(change ChangedEntity, confirmed []EntityLocation) bool {
	for _, entry := range confirmed {
		if entry.File == change.FilePath && entry.Line == change.StartLine {
			return true
		}
	}
	return false
}

func hopsWord(hops int) string {
	if hops == 1 {
		return "1 hop"
	}
	return itoa(hops) + " hops"
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	digits := ""
	for n > 0 {
		digits = string(rune('0'+n%10)) + digits
		n /= 10
	}
	return digits
}

func sameEntityName(claim, changed string) bool {
	if claim == changed {
		return true
	}
	lastDot := strings.LastIndex(claim, ".")
	return lastDot >= 0 && claim[lastDot+1:] == changed
}

