		t.Fatal(err)
	}
}

func trimmed(t *testing.T, repo string, args ...string) string {
	t.Helper()
	out := runGit(t, repo, args...)
	for len(out) > 0 && (out[len(out)-1] == '\n' || out[len(out)-1] == '\r') {
		out = out[:len(out)-1]
	}
	return out
}

