40	func parseVerifyIntentFlags(args []string) (verifyIntentFlags, string, error) {
41		flags := verifyIntentFlags{ConfigPath: "fidelity.config.yaml", OutputDirectory: "fidelity-out"}
42		var checkpointID string
43		for index := 0; index < len(args); index++ {
44			argument := args[index]
45			value := func() (string, error) {
46				index++
47				if index >= len(args) {
48					return "", fmt.Errorf("%s requires a value", argument)
49				}
50				return args[index], nil
51			}
52			var err error
53			switch argument {
54			case "--base":
55				flags.BaseCheckpointID, err = value()
56			case "--config":
57				flags.ConfigPath, err = value()
58			case "--out":
59				flags.OutputDirectory, err = value()
60			case "--repo":
61				flags.Repo, err = value()
62			default:
63				if strings.HasPrefix(argument, "-") {
64					return flags, "", fmt.Errorf("verify-intent received unexpected argument %q", argument)
65				}
66				if checkpointID != "" {
67					return flags, "", fmt.Errorf("verify-intent accepts exactly one checkpoint ID")
68				}
69				checkpointID = argument
70			}
71			if err != nil {
72				return flags, "", err
73			}
74		}
75		if checkpointID == "" {
76			return flags, "", fmt.Errorf("verify-intent requires a checkpoint ID")
77		}
78		return flags, checkpointID, nil
79	}
80	
81	type recordingFidelityStages struct{ stages []fidelity.Stage }
82	
83	func (runner *recordingFidelityStages) RunStage(_ context.Context, stage fidelity.Stage, _ fidelity.Request) error {
84		runner.stages = append(runner.stages, stage)
85		return nil
86	}
87	
88	func runVerifyIntent(ctx context.Context, opts Options, args []string) error {
89		return runVerifyIntentWithAdapter(ctx, opts, args, fidelity.NativeGraphAdapter{})
90	}
91	
92	func runVerifyIntentWithAdapter(ctx context.Context, opts Options, args []string, adapter fidelity.Adapter) error {
93		flags, checkpointID, err := parseVerifyIntentFlags(args)
94		if err != nil {
95			return err
96		}
97		repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
98		if err != nil {
99			return err
100		}
101		configPath := flags.ConfigPath
102		if !filepath.IsAbs(configPath) {
103			configPath = filepath.Join(repo, configPath)
104		}
105		config, err := fidelity.LoadConfig(configPath)
106		if err != nil {
107			return err
108		}
109		runner := &recordingFidelityStages{}
110		request := fidelity.Request{
111			CheckpointID: checkpointID, BaseCheckpointID: flags.BaseCheckpointID,
112			Config: config, OutputDirectory: flags.OutputDirectory,
113		}
114		if native, ok := adapter.(fidelity.NativeGraphAdapter); ok && native.Repo == "" {
115			native.Repo = repo
116			native.ProviderVersion = opts.Version
117			adapter = native
118		}
119		verification, err := (fidelity.Pipeline{Adapter: adapter, Runner: runner}).Run(ctx, request)
120		if err != nil {
121			return err
122		}
123		preflight := fidelity.CurrentPreflightReport()
124		verdict := fidelity.BuildVerdict(verification, preflight, config, time.Now())
125	
126		outputDirectory := flags.OutputDirectory
127		if !filepath.IsAbs(outputDirectory) {
128			outputDirectory = filepath.Join(repo, outputDirectory)
129		}
130		verdictPath, err := fidelity.WriteVerdict(outputDirectory, verdict)
131		if err != nil {
132			return err
133		}
134		reportPath := filepath.Join(outputDirectory, "VERIFY_REPORT.md")
135		if err := writeTextFile(reportPath, fidelity.RenderMarkdown(verdict)); err != nil {
136			return err
137		}
138		// opts.Stdout is the JSON response contract; the human-readable terminal
139		// report goes to stderr so scripted callers still get clean JSON on stdout.
140		fmt.Fprint(opts.Stderr, fidelity.RenderTerminal(verdict))
141	
142		response := verifyIntentResponse{
143			FormatVersion: 1, Status: "ok", CheckpointID: checkpointID,
144			BaseCheckpointID: flags.BaseCheckpointID, ConfigPath: configPath,
145			OutputDirectory: flags.OutputDirectory, Stages: runner.stages,
146			Preflight: preflight, Verification: verification,
147			Verdict: verdict, VerdictPath: verdictPath, ReportPath: reportPath,
148			Message: "capture, declaration, semantic-diff observation, six-tier reconciliation (including coverage-confidence), and verdict/report rendering are complete",
149		}
150		encoder := json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout))
151		encoder.SetEscapeHTML(false)
152		return encoder.Encode(response)
153	}
154	
155	func writeTextFile(path, content string) error {
156		return os.WriteFile(path, []byte(content), 0o644)
157	}
