package fidelity

import (
	"fmt"
	"sort"
)

// calibration.go implements Bible §12.1-12.3: the Databricks calibration
// gate's PURE MATH — Conformal Risk Control threshold selection and online
// gating. Both run with zero network access and zero Databricks dependency,
// so they are built and tested now, independent of workspace credentials.
// The only Databricks-dependent pieces are (1) the I-CALM extraction call
// that PRODUCES a VerbalConfidence for a real edge, and (2) AI Search
// corroboration for whatever the gate can't resolve — both wired through a
// small client interface (see databricks.go) so this file never needs to
// change once credentials arrive.

// CalibrationEdge is one labeled example for I-CALM calibration (§12.2): a
// heuristic edge with a verbal confidence score and a known ground-truth
// outcome, used to compute a statistically-bounded acceptance threshold.
type CalibrationEdge struct {
	EdgeType           string
	VerbalConfidence   float64 // the model's own reported confidence in [0,1]
	CorrectlyPredicted bool    // ground truth: was this edge actually correct?
}

// ConformalThreshold computes λ̂ (#48): the smallest threshold such that
// accepting only edges with VerbalConfidence >= λ̂ keeps the empirical
// false-positive rate on the calibration set at or below alpha.
//
// This assumes the standard Conformal Risk Control monotonicity property:
// risk (false-positive rate among ACCEPTED edges) is non-increasing as the
// threshold rises. Under that assumption, walking thresholds from strictest
// (1.0, accept nothing, risk 0) down to more permissive ones and stopping at
// the first violation gives the smallest threshold that still holds the
// target risk. Real math, no external service — MAPIE (§20.2) would replace
// this hand-rolled selection with a citable library implementation without
// changing the config surface (gate.mode) or verdict.json schema.
func ConformalThreshold(calibration []CalibrationEdge, alpha float64) (float64, error) {
	if len(calibration) == 0 {
		return 0, fmt.Errorf("conformal threshold requires a non-empty calibration set")
	}
	if alpha <= 0 || alpha >= 1 {
		return 0, fmt.Errorf("alpha must be between 0 and 1")
	}
	candidates := make([]float64, 0, len(calibration)+1)
	seen := map[float64]bool{1.0: true}
	candidates = append(candidates, 1.0)
	for _, edge := range calibration {
		if !seen[edge.VerbalConfidence] {
			seen[edge.VerbalConfidence] = true
			candidates = append(candidates, edge.VerbalConfidence)
		}
	}
	sort.Sort(sort.Reverse(sort.Float64Slice(candidates))) // strictest (1.0) first

	best := 1.0
	for _, threshold := range candidates {
		if conformalRisk(calibration, threshold) > alpha {
			break // this and every more-permissive threshold violates; keep the last good `best`
		}
		best = threshold
	}
	return best, nil
}

func conformalRisk(calibration []CalibrationEdge, threshold float64) float64 {
	accepted, falsePositives := 0, 0
	for _, edge := range calibration {
		if edge.VerbalConfidence >= threshold {
			accepted++
			if !edge.CorrectlyPredicted {
				falsePositives++
			}
		}
	}
	if accepted == 0 {
		return 0
	}
	return float64(falsePositives) / float64(accepted)
}

// ConformalRiskHolds verifies λ̂ actually holds the target false-positive
// rate on a held-out slice (the buildmap's own required test for #48).
func ConformalRiskHolds(heldOut []CalibrationEdge, threshold, alpha float64) bool {
	return conformalRisk(heldOut, threshold) <= alpha
}

// GateDecision is #50's online gating result for one advisory edge.
type GateDecision struct {
	ConformalGatePassed bool
	PendingVerification bool // epistemic abstention: below threshold, routed to corroboration, never silently trusted or dropped
}

// GateAdvisoryEdge implements §12.3's online gating. Deterministic edges
// never reach this function at all — classify.go's EdgeDeterministic bypass
// happens upstream, in reconciliation, not here. This only ever sees
// advisory edges.
func GateAdvisoryEdge(verbalConfidence, threshold float64) GateDecision {
	if verbalConfidence >= threshold {
		return GateDecision{ConformalGatePassed: true}
	}
	return GateDecision{ConformalGatePassed: false, PendingVerification: true}
}

package fidelity

import "testing"

// calibrationFixture is a synthetic set where higher verbal confidence
// genuinely correlates with correctness (the monotonicity CRC assumes),
// deliberately labeled synthetic per BUILDATHON.md's honesty requirement —
// not real production revert data.
func calibrationFixture() []CalibrationEdge {
	var edges []CalibrationEdge
	// High confidence, mostly correct (9/10 correct at 0.9+).
	for i := 0; i < 9; i++ {
		edges = append(edges, CalibrationEdge{VerbalConfidence: 0.95, CorrectlyPredicted: true})
	}
	edges = append(edges, CalibrationEdge{VerbalConfidence: 0.95, CorrectlyPredicted: false})
	// Mid confidence, roughly half correct.
	for i := 0; i < 5; i++ {
		edges = append(edges, CalibrationEdge{VerbalConfidence: 0.6, CorrectlyPredicted: i%2 == 0})
	}
	// Low confidence, mostly wrong.
	for i := 0; i < 8; i++ {
		edges = append(edges, CalibrationEdge{VerbalConfidence: 0.2, CorrectlyPredicted: i == 0})
	}
	return edges
}

func TestConformalThresholdHoldsTargetRiskOnCalibrationSet(t *testing.T) {
	calibration := calibrationFixture()
	threshold, err := ConformalThreshold(calibration, 0.05)
	if err != nil {
		t.Fatal(err)
	}
	if !ConformalRiskHolds(calibration, threshold, 0.05) {
		t.Fatalf("threshold %v does not hold alpha=0.05 on its own calibration set", threshold)
	}
	// The whole point of CRC: threshold must reject the low-confidence,
	// mostly-wrong tier and accept the high-confidence, mostly-right tier.
	if threshold < 0.9 {
		t.Fatalf("threshold = %v, want >= 0.9 (only the high-confidence tier meets 5%% risk here)", threshold)
	}
}

func TestConformalThresholdHoldsOnHeldOutSlice(t *testing.T) {
	// #48's required test: verify the computed threshold holds on data it
	// was NOT computed from, not just the set that produced it.
	trainSet := calibrationFixture()
	threshold, err := ConformalThreshold(trainSet, 0.05)
	if err != nil {
		t.Fatal(err)
	}
	heldOut := []CalibrationEdge{
		{VerbalConfidence: 0.97, CorrectlyPredicted: true},
		{VerbalConfidence: 0.93, CorrectlyPredicted: true},
		{VerbalConfidence: 0.91, CorrectlyPredicted: true},
		{VerbalConfidence: 0.6, CorrectlyPredicted: false}, // below threshold, must not count against it
	}
	if !ConformalRiskHolds(heldOut, threshold, 0.05) {
		t.Fatalf("threshold %v did not hold alpha=0.05 on a held-out slice", threshold)
	}
}

func TestConformalThresholdRejectsEmptyCalibrationSet(t *testing.T) {
	if _, err := ConformalThreshold(nil, 0.05); err == nil {
		t.Fatal("ConformalThreshold accepted an empty calibration set")
	}
}

func TestGateAdvisoryEdgeAbstainsRatherThanDropsBelowThreshold(t *testing.T) {
	pass := GateAdvisoryEdge(0.95, 0.9)
	if !pass.ConformalGatePassed || pass.PendingVerification {
		t.Fatalf("high-confidence edge = %#v, want gate passed", pass)
	}
	abstain := GateAdvisoryEdge(0.5, 0.9)
	if abstain.ConformalGatePassed || !abstain.PendingVerification {
		t.Fatalf("low-confidence edge = %#v, want epistemic abstention (pending_verification), not a silent drop", abstain)
	}
}

package fidelity

import (
	"context"
	"fmt"
)

// databricks.go is the seam §12's Databricks module calls through, mirroring
// adapter.go's own pattern: every real network/workspace call goes through
// one small interface, so wiring real credentials in later touches this file
// only — CalibrateAdvisoryEdges and the pure math in calibration.go never
// change.
type DatabricksClient interface {
	// ScoreEdge is §12.2's I-CALM extraction call: given an edge's hypothesis
	// in natural language and the constrained vocabulary it must ground to,
	// return a verbal confidence in [0,1]. Never invents a score outside that
	// range — same fail-closed posture as ResolveFallback (intent.go).
	ScoreEdge(ctx context.Context, hypothesis string, vocabulary []string) (float64, error)
	// Corroborate is §12.4's AI Search hybrid-retrieval call for a
	// pending_verification edge or an unverifiable_coverage entity (§12.15):
	// ask whether the repo's own docs/comments/commits confirm the
	// hypothesis. verified=false with no error means "no corroborating
	// evidence found," not a failure.
	Corroborate(ctx context.Context, hypothesis string) (verified bool, evidenceSnippet string, err error)
}

// UnavailableDatabricksClient is the safe default when calibration_enabled
// is false or no workspace is configured — every advisory/unverifiable
// entry's Databricks-reserved fields stay null, exactly as the schema
// promises (#26's "New fields ... null when it's off").
type UnavailableDatabricksClient struct{}

func (UnavailableDatabricksClient) ScoreEdge(context.Context, string, []string) (float64, error) {
	return 0, fmt.Errorf("Databricks client is not configured")
}

func (UnavailableDatabricksClient) Corroborate(context.Context, string) (bool, string, error) {
	return false, "", fmt.Errorf("Databricks client is not configured")
}

// CalibrateAdvisoryEdges implements §12.3/§12.5: for every advisory_low_confidence
// entry, score it via I-CALM, gate it against the conformal threshold, and — for
// anything the gate abstains on — attempt corroboration. Never touches
// unverifiable_coverage's baseline verification_path (#35's guarantee holds
// independent of this function ever running at all).
func CalibrateAdvisoryEdges(ctx context.Context, reconciliation *Reconciliation, client DatabricksClient, threshold float64) {
	for i := range reconciliation.AdvisoryLowConfidence {
		entry := &reconciliation.AdvisoryLowConfidence[i]
		confidence, err := client.ScoreEdge(ctx, entry.Reason, nil)
		if err != nil {
			continue // fail closed: leave verbal_confidence/conformal_gate_passed null, exactly as an unconfigured client would
		}
		entry.VerbalConfidence = &confidence
		decision := GateAdvisoryEdge(confidence, threshold)
		entry.ConformalGatePassed = &decision.ConformalGatePassed
		if !decision.PendingVerification {
			continue
		}
		entry.Corroboration.Attempted = true
		verified, snippet, err := client.Corroborate(ctx, entry.Reason)
		if err != nil {
			continue // corroboration attempted, verified stays nil — a failed lookup is not a "no"
		}
		entry.Corroboration.Verified = &verified
		if verified {
			entry.Corroboration.EvidenceSnippet = &snippet
		}
	}
}

// CorroborateUnverifiableCoverage implements §12.15: the Databricks-enhanced
// tier for the mandatory Curveball baseline (#35), never a substitute for
// it. A miss leaves VerificationPath unchanged — the baseline still holds.
func CorroborateUnverifiableCoverage(ctx context.Context, reconciliation *Reconciliation, client DatabricksClient) {
	for i := range reconciliation.UnverifiableCoverage {
		entry := &reconciliation.UnverifiableCoverage[i]
		entry.Corroboration.Attempted = true
		verified, snippet, err := client.Corroborate(ctx, entry.CoverageReason)
		if err != nil {
			continue
		}
		entry.Corroboration.Verified = &verified
		if verified {
			entry.Corroboration.EvidenceSnippet = &snippet
		}
	}
}

