49			UnverifiableCount: len(verdict.Reconciliation.UnverifiableCoverage),
50			DriftCount:        len(verdict.Reconciliation.UndeclaredScopeCreep) + len(verdict.Reconciliation.DeclaredUnimplemented),
51		}
52		var out bytes.Buffer
53		if err := dashboardTemplate.Execute(&out, data); err != nil {
54			return "", fmt.Errorf("render dashboard: %w", err)
55		}
56		return out.String(), nil
57	}
