59	type dashboardNode struct {
60		ID    string `json:"id"`
61		Label string `json:"label"`
62		Tier  string `json:"tier"`  // one of the four visual categories
63		Color string `json:"color"` // matches the terminal/Markdown renderer palette
64		// Zone drives the 3D radial layout: "core" (confirmed, center),
65		// "blast" (expected_blast_radius, distance = real hop count),
66		// "uncertain" (advisory, a fixed ring beyond the farthest real hop),
67		// "fog" (unverifiable_coverage, further out still, inside the scene's
68		// literal THREE.Fog — visually "the graph can't see clearly here"), and
69		// "outside" (undeclared_scope_creep, the farthest ring — confirmed
70		// drift, not uncertainty, so it stays sharp instead of foggy).
71		Zone string `json:"zone"`
72		// Hops is the real graph-reachability distance for "blast" nodes; 0 for
73		// every other zone, where distance is a fixed layout constant, not a
74		// graph fact — never conflate the two.
75		Hops int `json:"hops,omitempty"`
76	}
77	
78	type dashboardEdge struct {
79		Source string `json:"source"`
80		Target string `json:"target"`
81		Type   string `json:"type"`
82	}
83	
84	const (
85		colorConfirmed    = "#3fb950"
86		colorHeuristic    = "#d29922"
87		colorUnverifiable = "#bc8cff"
88		colorDrift        = "#f85149"
89	)
90	
91	// dashboardGraph builds the Graph View's nodes/edges. Real edges exist only
92	// for expected_blast_radius (the only tier carrying path_from_confirmed);
93	// every other tier contributes unconnected, tier-colored nodes.
94	func dashboardGraph(verdict Verdict) ([]dashboardNode, []dashboardEdge) {
95		var nodes []dashboardNode
96		var edges []dashboardEdge
97		seen := map[string]bool{}
98		addNode := func(id, label, tier, color, zone string, hops int) {
99			if id == "" || seen[id] {
100				return
101			}
102			seen[id] = true
103			nodes = append(nodes, dashboardNode{ID: id, Label: label, Tier: tier, Color: color, Zone: zone, Hops: hops})
104		}
105	
106		for _, entry := range verdict.Reconciliation.Confirmed {
107			addNode(entry.Entity, entry.Entity, "confirmed", colorConfirmed, "core", 0)
108		}
109		for _, entry := range verdict.Reconciliation.ExpectedBlastRadius {
110			// The path's own last element IS this entity's graph symbol ID
111			// (reachability.go appends the target itself), so labeling it with
112			// entry.Entity (the diff's short name) instead of the same
113			// lastSegment used for every other path node would silently create
114			// two disconnected nodes for one entity. Use the path consistently.
115			if len(entry.PathFromConfirmed) == 0 {
116				addNode(entry.Entity, entry.Entity, "expected_blast_radius", colorConfirmed, "blast", entry.Hops)
117				continue
118			}
119			for i := 0; i < len(entry.PathFromConfirmed)-1; i++ {
120				from, to := lastSegment(entry.PathFromConfirmed[i]), lastSegment(entry.PathFromConfirmed[i+1])
121				fromTier, toTier := "confirmed", "confirmed"
122				fromZone, toZone := "core", "core"
123				fromHops, toHops := 0, 0
124				if i+1 == len(entry.PathFromConfirmed)-1 {
125					toTier, toZone, toHops = "expected_blast_radius", "blast", entry.Hops
126				}
127				if i > 0 {
128					fromTier, fromZone, fromHops = "expected_blast_radius", "blast", i
129				}
130				addNode(from, from, fromTier, colorConfirmed, fromZone, fromHops)
131				addNode(to, to, toTier, colorConfirmed, toZone, toHops)
132				edgeType := ""
133				if i < len(entry.EdgeTypesTraversed) {
134					edgeType = entry.EdgeTypesTraversed[i]
135				}
136				edges = append(edges, dashboardEdge{Source: from, Target: to, Type: edgeType})
137			}
138		}
139		for _, entry := range verdict.Reconciliation.AdvisoryLowConfidence {
140			addNode(entry.Entity, entry.Entity, "advisory_low_confidence", colorHeuristic, "uncertain", 0)
141		}
142		for _, entry := range verdict.Reconciliation.UnverifiableCoverage {
143			addNode(entry.Entity, entry.Entity, "unverifiable_coverage", colorUnverifiable, "fog", 0)
144		}
145		for _, entry := range verdict.Reconciliation.UndeclaredScopeCreep {
146			addNode(entry.Entity, entry.Entity, "undeclared_scope_creep", colorDrift, "outside", 0)
147		}
148		if nodes == nil {
149			nodes = []dashboardNode{}
150		}
151		if edges == nil {
152			edges = []dashboardEdge{}
153		}
154		return nodes, edges
155	}
156	
157	// lastSegment reads a compound symbol ID the one positionally-safe way
158	// snapshot-format.md documents for a trailing field: anchor on the LAST
159	// separator. It is a display label, not an identity.
160	func lastSegment(id string) string {
161		for i := len(id) - 1; i >= 0; i-- {
162			if id[i] == ':' {
163				return id[i+1:]
164			}
165		}
166		return id
167	}
