169	type dashboardTemplateData struct {
170		VerdictJSON, GraphNodes, GraphEdges                           template.JS
171		CheckpointID, VerdictLabel                                    string
172		LabelConfirmed, LabelHeuristic, LabelUnverifiable, LabelDrift string
173		ConfirmedCount, HeuristicCount, UnverifiableCount, DriftCount int
174	}
175	
176	var dashboardTemplate = template.Must(template.New("dashboard").Parse(dashboardHTML))
177	
178	const dashboardHTML = `<!doctype html>
179	<html lang="en">
180	<head>
181	<meta charset="utf-8">
182	<title>Fidelity Verdict Dashboard</title>
183	<style>
184	  :root { color-scheme: dark; }
185	  body { margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; background:#0d1117; color:#c9d1d9; }
186	  header { padding:16px 24px; border-bottom:1px solid #30363d; }
187	  header h1 { margin:0; font-size:18px; }
188	  header .label { color:#8b949e; font-size:13px; }
189	  nav.tabs { display:flex; gap:4px; padding:0 24px; border-bottom:1px solid #30363d; }
190	  nav.tabs button { background:none; border:none; color:#8b949e; padding:10px 16px; cursor:pointer; font-size:14px; border-bottom:2px solid transparent; }
191	  nav.tabs button.active { color:#c9d1d9; border-bottom-color:#58a6ff; }
192	  section { padding:20px 24px; }
193	  section[hidden] { display:none; }
194	  .cards { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; margin-bottom:20px; }
195	  .card { border:1px solid #30363d; border-radius:8px; padding:14px; }
196	  .card .count { font-size:28px; font-weight:600; }
197	  .card .name { font-size:12px; color:#8b949e; margin-top:4px; }
198	  .tier { margin-bottom:18px; }
199	  .tier h3 { font-size:13px; text-transform:uppercase; letter-spacing:.04em; color:#8b949e; margin:0 0 6px; }
200	  .row { font-size:13px; padding:4px 0; border-bottom:1px solid #21262d; font-family:ui-monospace,monospace; }
201	  .row .loc { color:#8b949e; }
202	  #graph-canvas-wrap { position:relative; width:100%; height:70vh; border:1px solid #30363d; border-radius:8px; background:#050709; overflow:hidden; }
203	  #graph-canvas-wrap canvas { display:block; cursor:grab; }
204	  #graph-canvas-wrap canvas:active { cursor:grabbing; }
205	  #node-tooltip { position:absolute; pointer-events:none; background:#161b22; border:1px solid #30363d; border-radius:6px; padding:6px 10px; font-size:12px; display:none; max-width:280px; }
206	  .legend { display:flex; gap:16px; margin-top:10px; font-size:12px; color:#8b949e; flex-wrap:wrap; }
207	  .legend span { display:inline-flex; align-items:center; gap:6px; }
208	  .dot { width:10px; height:10px; border-radius:50%; display:inline-block; }
209	  .note { font-size:12px; color:#8b949e; margin-top:8px; }
210	</style>
211	</head>
212	<body>
213	<header>
214	  <h1>Fidelity Verdict — {{.CheckpointID}}</h1>
215	  <div class="label">{{.VerdictLabel}}</div>
216	</header>
217	<nav class="tabs">
218	  <button data-tab="summary" class="active">Summary</button>
219	  <button data-tab="graph">Graph View</button>
220	</nav>
221	<section id="summary-tab">
222	  <div class="cards">
223	    <div class="card" style="border-color:#3fb950"><div class="count" style="color:#3fb950">{{.ConfirmedCount}}</div><div class="name">{{.LabelConfirmed}}</div></div>
224	    <div class="card" style="border-color:#d29922"><div class="count" style="color:#d29922">{{.HeuristicCount}}</div><div class="name">{{.LabelHeuristic}}</div></div>
225	    <div class="card" style="border-color:#bc8cff"><div class="count" style="color:#bc8cff">{{.UnverifiableCount}}</div><div class="name">{{.LabelUnverifiable}}</div></div>
226	    <div class="card" style="border-color:#f85149"><div class="count" style="color:#f85149">{{.DriftCount}}</div><div class="name">{{.LabelDrift}}</div></div>
227	  </div>
228	  <div id="tier-lists"></div>
229	</section>
230	<section id="graph-tab" hidden>
231	  <div id="graph-canvas-wrap"><div id="node-tooltip"></div></div>
232	  <div class="legend">
233	    <span><i class="dot" style="background:#3fb950"></i>Core / Blast Radius — {{.LabelConfirmed}} (distance = real hop count)</span>
234	    <span><i class="dot" style="background:#d29922"></i>Uncertain ring — {{.LabelHeuristic}}</span>
235	    <span><i class="dot" style="background:#bc8cff"></i>Fog zone — {{.LabelUnverifiable}}</span>
236	    <span><i class="dot" style="background:#f85149"></i>Outside the blast radius — {{.LabelDrift}}</span>
237	  </div>
238	  <p class="note">Distance from center is a real graph fact ONLY inside the green blast radius (hop count from a confirmed change, connected by real traversed edges). The uncertain/fog/outside rings are fixed layout zones, not measured distances — advisory evidence sits in a ring, unverifiable-coverage entities are literally rendered inside the scene's fog (the graph could not see clearly there), and scope-creep sits outside it all: confirmed drift, not uncertainty. Drag to rotate, scroll to zoom.</p>
239	</section>
240	<script id="verdict-data" type="application/json">{{.VerdictJSON}}</script>
241	<script id="graph-nodes-data" type="application/json">{{.GraphNodes}}</script>
242	<script id="graph-edges-data" type="application/json">{{.GraphEdges}}</script>
243	<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
244	<script>
245	const verdict = JSON.parse(document.getElementById('verdict-data').textContent);
246	const graphNodes = JSON.parse(document.getElementById('graph-nodes-data').textContent);
247	const graphEdges = JSON.parse(document.getElementById('graph-edges-data').textContent);
248	
249	document.querySelectorAll('nav.tabs button').forEach(btn => {
250	  btn.addEventListener('click', () => {
251	    document.querySelectorAll('nav.tabs button').forEach(b => b.classList.remove('active'));
252	    btn.classList.add('active');
253	    document.getElementById('summary-tab').hidden = btn.dataset.tab !== 'summary';
254	    document.getElementById('graph-tab').hidden = btn.dataset.tab !== 'graph';
255	    if (btn.dataset.tab === 'graph') drawGraph();
256	  });
257	});
258	
259	function escapeHTML(s) {
260	  return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
261	}
262	
263	function renderTierLists() {
264	  const container = document.getElementById('tier-lists');
265	  const tiers = [
266	    ['Confirmed', verdict.reconciliation.confirmed, e => e.entity + ' — ' + (e.file||'') + ':' + (e.line||'') + ' [coverage: ' + e.coverage_confidence + ']'],
267	    ['Expected Blast Radius', verdict.reconciliation.expected_blast_radius, e => e.entity + ' — ' + (e.file||'') + ':' + (e.line||'') + ' — ' + e.hops + ' hop(s)'],
268	    ['Advisory Low Confidence', verdict.reconciliation.advisory_low_confidence, e => e.entity + ' — ' + e.reason],
269	    ['Unverifiable Coverage', verdict.reconciliation.unverifiable_coverage, e => e.entity + ' — ' + e.coverage_reason + ' [' + e.verification_path + ']'],
270	    ['Undeclared Scope Creep', verdict.reconciliation.undeclared_scope_creep, e => e.entity + ' — ' + e.reason + (e.community_label ? ' [community: ' + e.community_label + ']' : '')],
271	    ['Declared Unimplemented', verdict.reconciliation.declared_unimplemented, e => e.entity + ' — ' + e.reason],
272	  ];
273	  container.innerHTML = tiers.map(([title, entries, fmt]) => {
274	    if (!entries || entries.length === 0) return '';
275	    const rows = entries.map(e => '<div class="row">' + escapeHTML(fmt(e)) + '</div>').join('');
276	    return '<div class="tier"><h3>' + title + ' (' + entries.length + ')</h3>' + rows + '</div>';
277	  }).join('');
278	}
279	renderTierLists();
280	
281	// Radial "blast radius" layout: distance from the origin is a real graph
282	// fact (hop count) inside the blast zone, and a fixed zone ring everywhere
283	// else -- this scene never implies a measured distance it doesn't have.
284	const RING_UNIT = 55;      // world units per hop, inside the real blast radius
285	const RING_UNCERTAIN = 260; // advisory: fixed ring beyond the farthest plausible hop
286	const RING_FOG = 340;       // unverifiable_coverage: inside the literal scene fog
287	const RING_OUTSIDE = 430;   // undeclared_scope_creep: farthest, sharp (not foggy)
288	
289	function hashAngle(id) {
290	  let h = 0;
291	  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
292	  return h;
293	}
294	
295	function positionFor(node) {
296	  const h = hashAngle(node.id);
297	  const theta = (h % 1000) / 1000 * Math.PI * 2;
298	  const phi = ((h >> 10) % 1000) / 1000 * Math.PI;
299	  let radius;
300	  if (node.zone === 'core') radius = 12 + (h % 15);
301	  else if (node.zone === 'blast') radius = node.hops * RING_UNIT + (h % 20);
302	  else if (node.zone === 'uncertain') radius = RING_UNCERTAIN + (h % 40);
303	  else if (node.zone === 'fog') radius = RING_FOG + (h % 50);
304	  else radius = RING_OUTSIDE + (h % 60);
305	  return new THREE.Vector3(
306	    radius * Math.sin(phi) * Math.cos(theta),
307	    radius * Math.sin(phi) * Math.sin(theta),
308	    radius * Math.cos(phi)
309	  );
310	}
311	
312	let graphDrawn = false;
313	function drawGraph() {
314	  if (graphDrawn) return;
315	  graphDrawn = true;
316	  const wrap = document.getElementById('graph-canvas-wrap');
317	  const tooltip = document.getElementById('node-tooltip');
318	  const width = wrap.clientWidth || 800, height = wrap.clientHeight || 500;
319	
320	  const scene = new THREE.Scene();
321	  scene.background = new THREE.Color(0x050709);
322	  // The fog IS the visualization of coverage uncertainty: anything at or
323	  // beyond the fog ring fades into haze, exactly like an entity the graph
324	  // could not see clearly -- a real renderer feature standing in for a real
325	  // property of the data, not decoration.
326	  scene.fog = new THREE.Fog(0x050709, RING_UNCERTAIN, RING_FOG + 120);
327	
328	  const camera = new THREE.PerspectiveCamera(55, width / height, 1, 2000);
329	  camera.position.set(0, 120, 480);
330	
331	  const renderer = new THREE.WebGLRenderer({ antialias: true });
332	  renderer.setSize(width, height);
333	  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
334	  wrap.insertBefore(renderer.domElement, tooltip);
335	
336	  scene.add(new THREE.AmbientLight(0xffffff, 0.65));
337	  const point = new THREE.PointLight(0xffffff, 0.8);
338	  point.position.set(200, 300, 300);
339	  scene.add(point);
340	
341	  const group = new THREE.Group();
342	  scene.add(group);
343	
344	  // Faint reference rings at each real hop distance, so "farther = more
345	  // hops" reads as a measurement, not just a vibe.
346	  const maxHops = Math.max(1, ...graphNodes.filter(n => n.zone === 'blast').map(n => n.hops || 1));
347	  for (let hop = 1; hop <= maxHops; hop++) {
348	    const ringGeo = new THREE.RingGeometry(hop * RING_UNIT - 0.5, hop * RING_UNIT + 0.5, 64);
349	    const ringMat = new THREE.MeshBasicMaterial({ color: 0x3fb950, transparent: true, opacity: 0.12, side: THREE.DoubleSide });
350	    const ring = new THREE.Mesh(ringGeo, ringMat);
351	    ring.rotation.x = Math.PI / 2;
352	    group.add(ring);
353	  }
354	
355	  const positions = new Map();
356	  const meshByID = new Map();
357	  const sphereGeo = new THREE.SphereGeometry(6, 16, 16);
358	  graphNodes.forEach(n => {
359	    const pos = positionFor(n);
360	    positions.set(n.id, pos);
361	    const mat = new THREE.MeshStandardMaterial({
362	      color: n.color,
363	      transparent: n.zone === 'fog', opacity: n.zone === 'fog' ? 0.55 : 1,
364	      wireframe: n.zone === 'fog',
365	    });
366	    const mesh = new THREE.Mesh(sphereGeo, mat);
367	    mesh.position.copy(pos);
368	    mesh.userData = n;
369	    group.add(mesh);
370	    meshByID.set(n.id, mesh);
371	  });
372	
373	  graphEdges.forEach(e => {
374	    const from = positions.get(e.source), to = positions.get(e.target);
375	    if (!from || !to) return;
376	    const geo = new THREE.BufferGeometry().setFromPoints([from, to]);
377	    const mat = new THREE.LineBasicMaterial({ color: 0x3fb950 });
378	    group.add(new THREE.Line(geo, mat));
379	  });
380	
381	  // Hand-rolled orbit/zoom: drag to rotate the whole scene group, wheel to
382	  // dolly the camera. No extra script beyond three.js core itself.
383	  let dragging = false, lastX = 0, lastY = 0;
384	  renderer.domElement.addEventListener('mousedown', e => { dragging = true; lastX = e.clientX; lastY = e.clientY; });
385	  window.addEventListener('mouseup', () => { dragging = false; });
386	  renderer.domElement.addEventListener('mousemove', e => {
387	    if (dragging) {
388	      group.rotation.y += (e.clientX - lastX) * 0.005;
389	      group.rotation.x += (e.clientY - lastY) * 0.005;
390	      lastX = e.clientX; lastY = e.clientY;
391	    }
392	    const rect = renderer.domElement.getBoundingClientRect();
393	    pointerNDC.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
394	    pointerNDC.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
395	    tooltip.style.left = (e.clientX - rect.left + 12) + 'px';
396	    tooltip.style.top = (e.clientY - rect.top + 12) + 'px';
397	  });
398	  renderer.domElement.addEventListener('wheel', e => {
399	    e.preventDefault();
400	    camera.position.z = Math.max(80, Math.min(1200, camera.position.z + e.deltaY * 0.4));
401	  }, { passive: false });
402	
403	  const pointerNDC = new THREE.Vector2(-10, -10);
404	  const raycaster = new THREE.Raycaster();
405	  function animate() {
406	    requestAnimationFrame(animate);
407	    if (!dragging) group.rotation.y += 0.0015; // slow idle spin so the shape reads even before a viewer touches it
408	    raycaster.setFromCamera(pointerNDC, camera);
409	    const hits = raycaster.intersectObjects(Array.from(meshByID.values()));
410	    if (hits.length > 0) {
411	      const n = hits[0].object.userData;
412	      tooltip.style.display = 'block';
413	      tooltip.textContent = n.label + ' — ' + n.tier + (n.zone === 'blast' ? ' (' + n.hops + ' hop' + (n.hops === 1 ? '' : 's') + ')' : '');
414	    } else {
415	      tooltip.style.display = 'none';
416	    }
417	    renderer.render(scene, camera);
418	  }
419	  animate();
420	
421	  window.addEventListener('resize', () => {
422	    const w = wrap.clientWidth, h = wrap.clientHeight;
423	    camera.aspect = w / h; camera.updateProjectionMatrix();
424	    renderer.setSize(w, h);
425	  });
426	}
427	</script>
428	</body>
429	</html>
430	`
