18	// The Graph View draws an edge ONLY where a real path_from_confirmed exists
19	// (expected_blast_radius). Advisory/scope-creep/unverifiable-coverage nodes
20	// are placed and colored by tier but never connected by a fabricated edge —
21	// consistent with the whole project's refusal to present an absent
22	// relationship as a real one.
23	
24	func RenderDashboard(verdict Verdict) (string, error) {
25		verdictJSON, err := json.Marshal(verdict)
26		if err != nil {
27			return "", fmt.Errorf("encode verdict for dashboard: %w", err)
28		}
29		graphNodes, graphEdges := dashboardGraph(verdict)
