346	  let radius;
347	  if (node.zone === 'core') radius = 14 + (h % 15);
348	  else if (node.zone === 'blast') radius = node.hops * RING_UNIT + (h % 20);
349	  else if (node.zone === 'uncertain') radius = RING_UNCERTAIN + (h % 40);
350	  else if (node.zone === 'fog') radius = RING_FOG + (h % 50);
351	  else radius = RING_OUTSIDE + (h % 60);
352	  return new THREE.Vector3(
353	    radius * Math.sin(phi) * Math.cos(theta),
354	    radius * Math.sin(phi) * Math.sin(theta),
