368	  gradient.addColorStop(0, color); gradient.addColorStop(1, 'rgba(0,0,0,0)');
369	  ctx.fillStyle = gradient;
370	  ctx.fillRect(0, 0, size, size);
371	  return new THREE.CanvasTexture(canvas);
372	}
