import type { GraphNode, Zone } from '../graph'
import { ZONE_COLOR } from '../graph'
import type { Verdict } from '../types'

// Looks up the full reconciliation entry behind a clicked graph node, by
// entity name -- the graph itself only ever carries id/label/tier/zone/hops,
// everything else stays in one place, the fetched verdict.
function findEntry(verdict: Verdict, label: string): Record<string, unknown> | null {
  const tiers = [
    'confirmed',
    'expected_blast_radius',
    'advisory_low_confidence',
    'unverifiable_coverage',
    'undeclared_scope_creep',
  ] as const
  for (const tier of tiers) {
    const hit = (verdict.reconciliation[tier] as Array<Record<string, unknown>>).find(
      (entry) => entry.entity === label || (typeof entry.entity === 'string' && entry.entity.endsWith('.' + label)),
    )
    if (hit) return hit
  }
  return null
}

export function Inspector({ node, verdict, onClose }: { node: GraphNode | null; verdict: Verdict; onClose: () => void }) {
  const open = node !== null
  const entry = node ? findEntry(verdict, node.label) : null
  const tierColor = node ? ZONE_COLOR[node.zone as Zone] : '#ffffff'

  return (
    <div
      className={`absolute top-0 right-0 h-full w-[300px] bg-black/95 border-l border-line p-5 box-border overflow-y-auto z-30 transition-transform duration-300 ease-[cubic-bezier(.22,1,.36,1)] ${
        open ? 'translate-x-0' : 'translate-x-full'
      }`}
    >
      <button className="absolute top-3.5 right-3.5 text-muted text-lg" onClick={onClose} aria-label="Close inspector">
        ✕
      </button>
      {node && (
        <>
          <h4 className="font-serif text-base mb-1.5 break-words">{node.label}</h4>
          <span
            className="inline-block text-[10px] uppercase tracking-wide px-2.5 py-0.5 rounded-full mb-3.5"
            style={{ background: tierColor + '22', color: tierColor, border: `1px solid ${tierColor}55` }}
          >
            {node.tier}
          </span>
          <dl className="text-xs">
            {node.zone === 'blast' && (
              <>
                <dt className="text-muted mt-3">Hops from confirmed</dt>
                <dd className="mt-0.5 font-mono break-words">{node.hops}</dd>
              </>
            )}
            {entry &&
              Object.entries(entry)
                .filter(([, value]) => value !== null && value !== undefined && value !== '')
                .map(([key, value]) => (
                  <div key={key}>
                    <dt className="text-muted mt-3">{key}</dt>
                    <dd className="mt-0.5 font-mono break-words">
                      {typeof value === 'object' ? JSON.stringify(value) : String(value)}
                    </dd>
                  </div>
                ))}
          </dl>
        </>
      )}
    </div>
  )
}

import { LABEL_CONFIRMED, LABEL_DRIFT, LABEL_HEURISTIC, LABEL_UNVERIFIABLE } from '../types'
import type { Zone } from '../graph'

const ITEMS: { zones: Zone[]; color: string; text: string }[] = [
  { zones: ['core', 'blast'], color: '#3fb950', text: `Core / Blast Radius — ${LABEL_CONFIRMED} (distance = real hop count)` },
  { zones: ['uncertain'], color: '#d29922', text: `Uncertain ring — ${LABEL_HEURISTIC}` },
  { zones: ['fog'], color: '#bc8cff', text: `Fog zone — ${LABEL_UNVERIFIABLE}` },
  { zones: ['outside'], color: '#f85149', text: `Outside the blast radius — ${LABEL_DRIFT}` },
]

export function Legend({
  visibleZones,
  onToggle,
}: {
  visibleZones: Set<string>
  onToggle: (zones: Zone[], checked: boolean) => void
}) {
  return (
    <div className="flex gap-4 mt-3.5 text-xs text-muted flex-wrap items-center">
      {ITEMS.map((item) => (
        <label key={item.text} className="inline-flex items-center gap-1.5 cursor-pointer select-none">
          <input
            type="checkbox"
            checked={item.zones.every((zone) => visibleZones.has(zone))}
            onChange={(event) => onToggle(item.zones, event.target.checked)}
            style={{ accentColor: '#ff4500' }}
