import type { ReactNode } from 'react'
import { useReveal } from '../hooks/useReveal'

export function TierCard({
  count,
  label,
  color,
  delayMs = 0,
}: {
  count: number
  label: ReactNode
  color: string
  delayMs?: number
}) {
  const { ref, active } = useReveal<HTMLDivElement>()
  return (
    <div
      ref={ref}
      data-active={active}
      className="reveal bg-card border border-line rounded-[20px] p-5.5 transition-all duration-400 ease-[cubic-bezier(.22,1,.36,1)] hover:-translate-y-1"
      style={
        {
          transitionDelay: `${delayMs}ms`,
          '--tw-shadow': `0 16px 40px -12px ${color}40`,
        } as React.CSSProperties
      }
      onMouseEnter={(e) => {
        e.currentTarget.style.borderColor = color
        e.currentTarget.style.boxShadow = `0 16px 40px -12px ${color}40`
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.borderColor = ''
        e.currentTarget.style.boxShadow = ''
      }}
    >
      <div className="font-serif text-4xl font-semibold leading-none" style={{ color }}>
        {count}
      </div>
      <div className="text-xs text-muted mt-2.5 uppercase tracking-wide">{label}</div>
    </div>
  )
}

import type { ReactNode } from 'react'
import { useReveal } from '../hooks/useReveal'

export function TierList<T>({ title, entries, format }: { title: string; entries: T[]; format: (entry: T) => ReactNode }) {
  const { ref, active } = useReveal<HTMLDivElement>()
  if (entries.length === 0) return null
  return (
    <div ref={ref} data-active={active} className="reveal mb-5.5">
      <h3 className="text-xs uppercase tracking-wider text-muted mb-2 font-medium">
        {title} ({entries.length})
      </h3>
      {entries.map((entry, index) => (
        <div key={index} className="text-[13px] py-1.5 border-b border-line font-mono">
          {format(entry)}
        </div>
      ))}
    </div>
  )
}

import type { Verdict } from '../types'
import { LABEL_CONFIRMED, LABEL_DRIFT, LABEL_HEURISTIC, LABEL_UNVERIFIABLE } from '../types'
import { TierCard } from './TierCard'
import { TierList } from './TierList'

export function SummaryTab({ verdict }: { verdict: Verdict }) {
  const r = verdict.reconciliation
  const confirmedCount = r.confirmed.length + r.expected_blast_radius.length
  const driftCount = r.undeclared_scope_creep.length + r.declared_unimplemented.length

  return (
    <section className="px-7 pb-16">
      <div className="grid grid-cols-4 gap-4 mb-7">
        <TierCard count={confirmedCount} label={LABEL_CONFIRMED} color="#3fb950" />
        <TierCard count={r.advisory_low_confidence.length} label={LABEL_HEURISTIC} color="#d29922" delayMs={80} />
        <TierCard count={r.unverifiable_coverage.length} label={LABEL_UNVERIFIABLE} color="#bc8cff" delayMs={160} />
        <TierCard count={driftCount} label={LABEL_DRIFT} color="#f85149" delayMs={240} />
      </div>

      <TierList
        title="Confirmed"
        entries={r.confirmed}
        format={(e) => (
          <>
            {e.entity} — {e.file ?? ''}:{e.line ?? ''} [coverage: {e.coverage_confidence}]
          </>
        )}
      />
      <TierList
        title="Expected Blast Radius"
        entries={r.expected_blast_radius}
        format={(e) => (
          <>
            {e.entity} — {e.file ?? ''}:{e.line ?? ''} — {e.hops} hop(s)
          </>
        )}
      />
      <TierList
        title="Advisory Low Confidence"
        entries={r.advisory_low_confidence}
        format={(e) => (
          <>
            {e.entity} — {e.reason}
          </>
        )}
      />
      <TierList
        title="Unverifiable Coverage"
        entries={r.unverifiable_coverage}
        format={(e) => (
          <>
            {e.entity} — {e.coverage_reason} [{e.verification_path}]
          </>
        )}
      />
      <TierList
        title="Undeclared Scope Creep"
        entries={r.undeclared_scope_creep}
        format={(e) => (
          <>
            {e.entity} — {e.reason}
            {e.community_label ? ` [community: ${e.community_label}]` : ''}
          </>
        )}
      />
      <TierList
        title="Declared Unimplemented"
        entries={r.declared_unimplemented}
        format={(e) => (
          <>
            {e.entity} — {e.reason}
          </>
        )}
      />
    </section>
  )
}

import { useEffect, useState } from 'react'

export function Header({ checkpointId, verdictLabel }: { checkpointId: string; verdictLabel: string }) {
  const [scrolled, setScrolled] = useState(false)

  useEffect(() => {
    function onScroll() {
      setScrolled(window.scrollY > 20)
    }
    window.addEventListener('scroll', onScroll)
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  const isReview = verdictLabel === 'REVIEW_REQUIRED'

  return (
    <header
      className={`sticky top-0 z-10 transition-all duration-400 border-b ${
        scrolled ? 'py-3 bg-black/85 backdrop-blur-md border-line' : 'py-5.5 border-transparent'
      }`}
    >
      <div className="px-7">
        <h1 className="font-serif text-[22px] font-semibold tracking-tight m-0">
          Fidelity<span className="text-accent">.</span>
        </h1>
        <div className="flex items-center gap-2.5 mt-1 text-xs text-muted font-mono">
          <span>{checkpointId}</span>
          <span
            className={`inline-flex items-center px-3 py-0.5 rounded-full text-[11px] uppercase tracking-wide border ${
