            {verdictLabel}
          </span>
        </div>
      </div>
    </header>
  )
}

export type Tab = 'summary' | 'graph'

export function TabNav({ tab, onChange }: { tab: Tab; onChange: (tab: Tab) => void }) {
  const tabs: { id: Tab; label: string }[] = [
    { id: 'summary', label: 'Summary' },
